package ma.maarifculture.analytics.service;
import java.util.List;import ma.maarifculture.analytics.dto.SettingDtos.*;import ma.maarifculture.analytics.exception.ResourceNotFoundException;import ma.maarifculture.analytics.model.AppSetting;import ma.maarifculture.analytics.repository.AppSettingRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class SettingService {private final AppSettingRepository settings;private final CurrentUserService current;private final AuditService audit;public SettingService(AppSettingRepository s,CurrentUserService c,AuditService a){settings=s;current=c;audit=a;}public List<SettingResponse> list(){return settings.findAll().stream().map(this::response).toList();}@Transactional public SettingResponse update(String key,SettingRequest request){AppSetting s=settings.findById(key).orElseThrow(()->new ResourceNotFoundException("Paramètre introuvable : "+key));var actor=current.required();s.update(request.value(),request.description(),actor);audit.record(actor,"SETTING_UPDATED","AppSetting",key,null);return response(s);}private SettingResponse response(AppSetting s){return new SettingResponse(s.getKey(),s.getValue(),s.getDescription(),s.getUpdatedAt());}}
